import * as z from "zod";

const BookingRequest = z.object({
  seats: z.number().int().min(1).max(20),
  date: z.string().min(1),
});

const parsed = BookingRequest.safeParse(body);
if (!parsed.success) {
  return problem(422, parsed.error.issues); // Issue[]: path, code, message
}
return createBooking(parsed.data);

class BookingRequest {
  @IsInt() @Min(1) @Max(20)
  seats!: number;

  @IsISO8601()
  date!: string;
}

const errors: ValidationError[] =
  await validate(plainToInstance(BookingRequest, body));
if (errors.length > 0) return problem(422, flatten(errors)); // every property
